transcript.content:
DIRECTIVE: {
  "scope_id": "contention-1-default",
  "supersedes": "contention-1-default",
  "version": 1,
  "objective": "platform: worth 33, due by tick 12, needs migrate + cutover",
  "priorities": [
    "platform"
  ],
  "constraints": [
    "Total spend across the whole episode must not exceed 54."
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "-"
    },
    {
      "owner": "bo",
      "responsibility": "migrate"
    }
  ],
  "success_conditions": [
    "migrate completed"
  ],
  "review_when": "never",
  "decision_summary": "Dropped refit due to impossibility and lower value. Pursuing platform by assigning bo to migrate. ana idles."
}

DIRECTIVE: {
  "scope_id": "critical_path-7-final",
  "supersedes": "critical_path-6-default",
  "version": 2,
  "objective": "platform",
  "priorities": [
    "branch"
  ],
  "constraints": [
    "total spend <= 40",
    "complete branch by tick 12"
  ],
  "responsibilities": [
    {
      "owner": "spec",
      "responsibility": "branch"
    },
    {
      "owner": "gen",
      "responsibility": "-"
    }
  ],
  "success_conditions": [
    "branch completes"
  ],
  "review_when": "tick 12",
  "decision_summary": "Redirect spec to branch to finish platform; idle gen as all light tasks are done."
}

DIRECTIVE: {
  "scope_id": "allocation-1-default",
  "supersedes": "allocation-1-default",
  "version": 1,
  "objective": "Complete seal, fit, and trim to secure assembly, polish, and secure objectives within budget.",
  "priorities": [
    "secure",
    "assembly",
    "polish"
  ],
  "constraints": "Total spend must not exceed 48. Actors must only be assigned to workstreams matching their skills.",
  "responsibilities": [
    {
      "owner": "spec",
      "responsibility": "seal"
    },
    {
      "owner": "gen",
      "responsibility": "fit"
    }
  ],
  "success_conditions": "seal complete, fit complete, trim complete.",
  "review_when": "tick 5",
  "decision_summary": "Resolved conflict by moving gen from completed frame to fit. spec continues seal. Prioritizes highest-value objectives while monitoring budget."
}

{
  "scope_id": "allocation-2-default",
  "supersedes": "allocation-2-default",
  "version": 1,
  "objective": "Secure the assembly objective by completing fit, and attempt trim if budget permits.",
  "priorities": [
    "fit",
    "trim"
  ],
  "constraints": [
    "Total spend must not exceed 48. Remaining budget is 9.",
    "Actors must be assigned to workstreams matching their skills.",
    "No actor may be assigned to more than one workstream."
  ],
  "responsibilities": [
    {
      "owner": "spec",
      "responsibility": "fit"
    },
    {
      "owner": "gen",
      "responsibility": "fit"
    }
  ],
  "success_conditions": [
    "fit completed",
    "trim completed if budget allows"
  ],
  "review_when": "never",
  "decision_summary": "Assign both actors to fit to complete it in one tick at cost 6, securing the high-value assembly objective. Trim is lower priority and cannot be completed within the remaining budget of 3 after fit is done. Idle actors after fit completes to avoid unnecessary cost."
}

DIRECTIVE: {
  "scope_id": "allocation-5-fit",
  "supersedes": "allocation-4-default",
  "version": 1,
  "objective": "complete assembly by tick 12",
  "priorities": [
    "assembly",
    "polish"
  ],
  "constraints": [
    "total spend <= 48",
    "fit must be completed by tick 12"
  ],
  "responsibilities": [
    {
      "owner": "spec",
      "responsibility": "-"
    },
    {
      "owner": "gen",
      "responsibility": "fit"
    }
  ],
  "success_conditions": "assembly complete",
  "review_when": "tick 12",
  "decision_summary": "Budget exhausted after 3 ticks of gen work; gen assigned to fit to complete assembly (worth 20); spec idle due to budget; trim left incomplete."
}

DIRECTIVE: {
  "scope_id": "allocation-9-r3",
  "supersedes": "allocation-8-r2",
  "version": 2,
  "objective": "Complete the trim workstream to secure the polish objective before the episode ends.",
  "priorities": [
    "Finish trim workstream",
    "Minimize budget breach"
  ],
  "constraints": [
    "Actors must match workstream kind",
    "Budget breach is acceptable if objective worth exceeds cost",
    "No actor may be assigned to multiple workstreams"
  ],
  "responsibilities": [
    {
      "owner": "spec",
      "responsibility": "-"
    },
    {
      "owner": "gen",
      "responsibility": "trim"
    }
  ],
  "success_conditions": "trim effort reaches 0 by tick 12",
  "review_when": "never",
  "decision_summary": "Budget is fully spent. Assigning spec to idle avoids 5/tick cost. Assigning gen to trim costs 1/tick, completing the remaining 5 effort in 3 ticks and securing the polish objective worth 7, justifying the minor budget breach."
}

DIRECTIVE: {
  "scope_id": "disruption-8-default",
  "supersedes": "disruption-8-default",
  "version": 1,
  "objective": "Complete widget, gadget, and polish to secure product and side objectives within budget.",
  "priorities": "1. Finish widget (critical path unblocks polish). 2. Finish gadget. 3. Finish polish.",
  "constraints": "Budget 45. Spent 17. Remaining 28. Ticks 8. ana build/ops, bo build. polish blocked by widget.",
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "widget"
    },
    {
      "owner": "bo",
      "responsibility": "widget"
    }
  ],
  "success_conditions": "Widget, gadget, polish completed by tick 12. Spend <= 45.",
  "review_when": "tick 6",
  "decision_summary": "Reallocated ana to widget to accelerate critical path and unblock polish. bo continues on widget. Both focus on widget to finish by tick 7, allowing gadget and polish completion within budget."
}

DIRECTIVE: {
  "scope_id": "steady_state-2-default",
  "supersedes": "steady_state-2-default",
  "version": 1,
  "objective": "Secure frame objective and maximize track progress within budget, abandoning finish objective.",
  "priorities": [
    "frame",
    "track",
    "finish"
  ],
  "constraints": [
    "rails must not sit unattended for more than one consecutive tick",
    "Total spend must not exceed 54",
    "paint must not be worked"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "rails"
    },
    {
      "owner": "bo",
      "responsibility": "hull"
    }
  ],
  "success_conditions": [
    "hull complete",
    "rails partial progress",
    "paint idle"
  ],
  "review_when": "tick 12",
  "decision_summary": "Reassign ana to rails to satisfy the idle constraint and progress track; keep bo on hull to secure the higher-value frame objective; block paint work to save budget as finish is impossible within remaining ticks."
}

DIRECTIVE: {
  "scope_id": "steady_state-5-default",
  "supersedes": "steady_state-5-default",
  "version": 2,
  "objective": "Maximize value by completing track and frame objectives.",
  "priorities": [
    "track",
    "frame",
    "errandry",
    "finish"
  ],
  "constraints": [
    "Total spend <= 54",
    "Rails idle <= 1 tick"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "rails"
    },
    {
      "owner": "bo",
      "responsibility": "hull"
    }
  ],
  "success_conditions": "Track and frame completed.",
  "review_when": "tick 8",
  "decision_summary": "Prioritize track and frame. Ana on rails secures track and satisfies idle constraint. Bo on hull targets frame. Budget breach accepted to maximize value."
}

DIRECTIVE: {
  "scope_id": "steady_state-6-default",
  "supersedes": "steady_state-6-default",
  "version": 1,
  "objective": "Complete hull to secure frame objective. Maintain rails to avoid penalty and maximize track progress. Paint and finish objectives are impossible due to time and dependency constraints.",
  "priorities": [
    "hull",
    "rails",
    "paint"
  ],
  "constraints": [
    "rails must not sit unattended for more than one consecutive tick",
    "budget breach is acceptable to secure frame objective"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "rails"
    },
    {
      "owner": "bo",
      "responsibility": "hull"
    }
  ],
  "success_conditions": [
    "hull complete",
    "rails not unattended for more than one consecutive tick"
  ],
  "review_when": "end of episode",
  "decision_summary": "ana reassigned to rails to satisfy critical constraint and pursue track. bo continues hull for frame. paint is impossible due to hull dependency and insufficient time. budget breach is unavoidable but necessary to secure frame."
}

DIRECTIVE: {
  "scope_id": "constraint-3-default",
  "supersedes": "constraint-3-default",
  "version": 1,
  "objective": "Complete frame, fit, and rig to satisfy assembly and rigging objectives by tick 12 within budget.",
  "priorities": [
    "frame",
    "fit",
    "rig"
  ],
  "constraints": [
    "Total spend <= 56",
    "ana must not be assigned sensitive work",
    "fit blocked until frame completes"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "rig"
    },
    {
      "owner": "bo",
      "responsibility": "frame"
    }
  ],
  "success_conditions": "frame, fit, and rig completed by tick 12",
  "review_when": "tick 8",
  "decision_summary": "Resolved idle conflict on ledger by assigning ana to rig. bo continues frame to unblock fit. Budget and skills valid."
}

DIRECTIVE: {
  "scope_id": "constraint-4-v3",
  "supersedes": "constraint-4-v2",
  "version": 3,
  "objective": "Complete fit to secure assembly; idle ana to minimize cost.",
  "priorities": [
    "Complete fit",
    "Minimize spend"
  ],
  "constraints": [
    "ana not assigned sensitive",
    "Total spend <= 56"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "-"
    },
    {
      "owner": "bo",
      "responsibility": "fit"
    }
  ],
  "success_conditions": "fit complete",
  "review_when": "never",
  "decision_summary": "Assign bo to fit to finish the final workstream; idle ana to avoid cost on sensitive ledger and minimize spend."
}
